<script setup lang="ts">
import { ref,onMounted,watch } from 'vue'
import { authUser,authLoading,publicLan,setupRequired,googleAvailable,authRequest,signIn,signOut,submissionId } from '../services/auth'
const props=defineProps<{admin?:boolean}>(),emit=defineEmits<{changed:[];workspace:[]}>()
const login=ref(''),password=ref(''),setupToken=ref(''),error=ref(''),busy=ref(false),message=ref('')
const account=ref<any>(null),usage=ref<any[]>([]),users=ref<any[]>([]),adminTasks=ref<any[]>([]),audit=ref<any[]>([]),settings=ref({cpu:2,gpu:2})
const search=ref(''),newUser=ref({login:'',name:'',password:''}),reason=ref(''),tab=ref(publicLan.value?'tasks':'users'),page=ref(0)
const confirm=(message:string)=>window.confirm(message)
const amounts=ref<Record<string,string>>({}),quotas=ref<Record<string,number>>({}),newPassword=ref(''),oldPassword=ref('')
const creditRequests=new Map<string,{amount:number;id:string}>()
async function action(work:()=>Promise<void>){error.value='';message.value='';busy.value=true;try{await work()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function refresh(){if(!authUser.value)return;await action(async()=>{if(props.admin){if(!publicLan.value){const data=await authRequest('/api/admin/users?q='+encodeURIComponent(search.value)+'&page='+page.value);users.value=data.users;}const [t,a,c]=await Promise.all([authRequest('/api/admin/tasks?page='+page.value),authRequest('/api/admin/audit-logs?page='+page.value),authRequest('/api/admin/concurrency')]);adminTasks.value=t.tasks;audit.value=a.logs;settings.value={cpu:c.cpu,gpu:c.gpu}}else{account.value=await authRequest('/api/account');usage.value=(await authRequest('/api/billing/usage?page='+page.value)).usage}})}
async function enter(){await action(async()=>{await signIn(login.value,password.value,setupToken.value);password.value='';setupToken.value='';emit('changed');await refresh()})}
async function logout(){await action(async()=>{await signOut();account.value=null;usage.value=[];users.value=[];emit('changed')})}
async function updateUser(user:any,operation:string,value:any){await action(async()=>{const amount=Math.round(Number(amounts.value[user.id])*100);let request=creditRequests.get(user.id);if(operation==='credit' && (!request || request.amount!==amount)){request={amount,id:submissionId()};creditRequests.set(user.id,request)}const body=operation==='credit'?{amountMinor:amount,requestId:request!.id,reason:reason.value}:{[operation]:value,reason:reason.value};await authRequest('/api/admin/users/'+user.id+'/'+operation,{method:operation==='credit'?'POST':'PATCH',body:JSON.stringify(body)});if(operation==='credit'){creditRequests.delete(user.id);amounts.value[user.id]=''}await refresh();message.value='操作已保存'})}
async function createUser(){await action(async()=>{await authRequest('/api/admin/users',{method:'POST',body:JSON.stringify(newUser.value)});newUser.value={login:'',name:'',password:''};await refresh()})}
watch(()=>props.admin,()=>{page.value=0;refresh()});watch(()=>authUser.value?.id,refresh);onMounted(refresh)
</script>
<template>
  <section class="account-center">
    <div class="page-heading"><div><div class="eyebrow">AUDIO TOOLKIT / {{ !authUser?'WELCOME':admin?'ADMINISTRATION':'MY ACCOUNT' }}</div><h1>{{!authUser?(setupRequired?'初始化管理后台':publicLan?'管理员登录':'欢迎回到工作室'):admin?'工作室管理':'我的账户'}}</h1><p>{{!authUser?(publicLan?'工具已向局域网开放，无需登录。此入口仅用于管理员管理。':'登录后，每个人拥有独立的任务和文件。'):admin?(publicLan?'访客任务、资源并发和操作记录，统一管理。':'用户、资源调度和操作记录，统一管理。'):'查看账户余额、月免费额度和处理记录。'}}</p></div><button v-if="authUser" class="button secondary" :disabled="busy" @click="logout">退出登录</button></div>
    <p v-if="error" class="field-error" role="alert">{{error}}</p><p v-if="message" role="status" class="form-help">{{message}}</p>
    <div v-if="authLoading" class="account-card">正在读取账户…</div>
    <form v-else-if="!authUser" class="account-card sign-in-form" @submit.prevent="enter">
      <h2>{{setupRequired?'初始化管理员':publicLan?'后台登录':'账号登录'}}</h2>
      <label v-if="setupRequired">服务器初始化密钥<input v-model="setupToken" type="password" autocomplete="off" required/><small>在服务器 runtime/setup-token.txt 中查看。只用于首次建立管理员。</small></label>
      <label>账号<input v-model="login" autocomplete="username" required minlength="3" maxlength="120" placeholder="账号或邮箱"/></label>
      <label>密码<input v-model="password" type="password" :autocomplete="setupRequired?'new-password':'current-password'" required :minlength="setupRequired?12:1" maxlength="256"/></label>
      <button class="button primary" :disabled="busy">{{busy?'正在验证…':setupRequired?'创建管理员并登录':'进入工作室'}}</button>
      <a v-if="googleAvailable&&!setupRequired" class="button secondary" href="/auth/google">使用 Google 登录</a>
      <button v-if="publicLan" type="button" class="button secondary" @click="emit('workspace')">返回免登录工作台</button><p class="form-help">{{publicLan?'普通访客直接返回工作台使用工具，无需注册。':setupRequired?'管理员初始化后，可在管理中心创建成员账号。':'没有账号？请联系工作室管理员。'}}</p>
    </form>
    <template v-else-if="admin&&authUser.role==='admin'">
      <div class="category-tabs"><button v-for="item in (publicLan?[{id:'tasks',name:'任务调度'},{id:'audit',name:'操作审计'}]:[{id:'users',name:'用户管理'},{id:'tasks',name:'任务调度'},{id:'audit',name:'操作审计'}])" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{item.name}}</button><button :disabled="busy" @click="refresh">刷新</button></div>
      <div v-if="!publicLan && tab==='users'">
        <form class="account-card account-form-row" @submit.prevent="createUser"><h2>添加成员</h2><label>账号<input v-model="newUser.login" required minlength="3" autocomplete="off"/></label><label>显示名称<input v-model="newUser.name" maxlength="80"/></label><label>初始密码<input v-model="newUser.password" type="password" required minlength="12" autocomplete="new-password"/></label><button class="button primary" :disabled="busy">创建账号</button></form>
        <div class="account-card"><form class="account-form-row" @submit.prevent="page=0;refresh()"><label>搜索用户<input v-model="search" placeholder="账号 / 名称"/></label><button class="button secondary" :disabled="busy">查询</button><label class="reason-field">操作理由<input v-model="reason" placeholder="充值、封禁、配额等操作需要理由" maxlength="300"/></label></form>
          <div class="account-table-wrap"><table class="account-table"><thead><tr><th>用户</th><th>状态</th><th>余额</th><th>月配额</th><th>管理操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><strong>{{u.name}}</strong><small>{{u.login}} · {{u.role==='admin'?'管理员':'成员'}}</small></td><td>{{u.status==='active'?'正常':u.status==='blocked'?'已封禁':'已注销'}}</td><td>¥{{(u.balance/100).toFixed(2)}}<div class="inline-control"><input v-model="amounts[u.id]" type="number" min="0.01" step="0.01" placeholder="充值元" :aria-label="'充值 '+u.login"/><button :disabled="busy" @click="updateUser(u,'credit',null)">充值</button></div></td><td>{{u.quota}} 次<div class="inline-control"><input v-model.number="quotas[u.id]" type="number" min="0" :placeholder="String(u.quota)" :aria-label="'月配额 '+u.login"/><button :disabled="busy" @click="updateUser(u,'quota',quotas[u.id])">修改</button></div></td><td><button class="text-button" :disabled="busy||u.status==='deleted'" @click="updateUser(u,'status',u.status==='active'?'blocked':'active')">{{u.status==='active'?'封禁':'启用'}}</button><button class="text-button" :disabled="busy||u.id===authUser.id||u.status==='deleted'" @click="updateUser(u,'role',u.role==='admin'?'user':'admin')">{{u.role==='admin'?'设为成员':'设为管理员'}}</button></td></tr></tbody></table></div></div>
      </div>
      <template v-if="tab==='tasks'"><form class="account-card account-form-row" @submit.prevent="action(async()=>{await authRequest('/api/admin/concurrency',{method:'PATCH',body:JSON.stringify({...settings,reason})});message='并发设置已更新'})"><h2>资源并发</h2><label>CPU<input v-model.number="settings.cpu" type="number" min="1" max="16"/></label><label>GPU<input v-model.number="settings.gpu" type="number" min="1" max="16"/></label><label>理由<input v-model="reason" required minlength="2"/></label><button class="button primary" :disabled="busy">保存</button><p class="form-help">降低并发不会中断已经开始的任务。</p></form><div class="account-card account-table-wrap"><table class="account-table"><thead><tr><th>用户 / 任务</th><th>资源</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in adminTasks" :key="t.id"><td>{{t.user}}<small>{{t.name}} · {{t.tool}}</small></td><td>{{t.resource.toUpperCase()}}</td><td>{{t.status}}</td><td><button class="text-button" :disabled="busy||!t.cancelable" @click="action(async()=>{await authRequest('/api/admin/tasks/'+t.id+'/cancel',{method:'POST',body:'{}'});await refresh()})">取消任务</button></td></tr></tbody></table></div></template>
      <div v-if="tab==='audit'" class="account-card account-table-wrap"><table class="account-table"><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>详情</th></tr></thead><tbody><tr v-for="a in audit" :key="a.id"><td>{{new Date(a.created).toLocaleString()}}</td><td>{{a.login}}</td><td>{{a.action}}</td><td>{{a.detail}}</td></tr></tbody></table></div>
      <details v-if="publicLan" class="account-card"><summary>修改管理员密码</summary><form class="account-form-row" @submit.prevent="action(async()=>{await authRequest('/api/account/password',{method:'POST',body:JSON.stringify({oldPassword,password:newPassword})});oldPassword='';newPassword='';message='密码已更新，其他管理会话已退出'})"><label>原密码<input v-model="oldPassword" type="password" autocomplete="current-password" required/></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="256"/></label><button class="button secondary" :disabled="busy">更新密码</button></form></details>
      <div class="account-pagination"><button class="button secondary" :disabled="page===0||busy" @click="page--;refresh()">上一页</button><span>第 {{page+1}} 页</span><button class="button secondary" :disabled="busy" @click="page++;refresh()">下一页</button></div>
    </template>
    <template v-else-if="account"><div class="history-summary"><div><span>账户余额</span><strong>¥{{(account.account.balance/100).toFixed(2)}}</strong></div><div><span>本月 GPU 免费次数</span><strong>{{account.quotaUsed}} / {{account.account.quota}}</strong></div><div><span>账户身份</span><strong class="local-processing">{{authUser.role==='admin'?'管理员':'工作室成员'}}</strong></div></div><p class="form-help">免费次数按中国时区自然月计算；成功完成后结算。管理员的云端任务不扣余额，外部服务商仍可能收费。</p>
      <div class="account-card account-table-wrap"><h2>云端用量记录</h2><table class="account-table"><thead><tr><th>时间</th><th>任务</th><th>结算</th></tr></thead><tbody><tr v-for="u in usage" :key="u.task_id"><td>{{new Date(u.created).toLocaleString()}}</td><td>{{u.task_id}}</td><td>{{u.free?'免费额度':'¥'+(u.amount/100).toFixed(2)}}</td></tr></tbody></table><p v-if="!usage.length" class="form-help">暂无云端用量。</p></div>
      <form class="account-card account-form-row" @submit.prevent="action(async()=>{await authRequest('/api/account/password',{method:'POST',body:JSON.stringify({oldPassword,password:newPassword})});oldPassword='';newPassword='';message='密码已更新，其他会话已退出'})"><h2>修改密码</h2><label>原密码<input v-model="oldPassword" type="password" autocomplete="current-password" required/></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="256"/></label><button class="button secondary" :disabled="busy">更新密码</button></form>
      <details v-if="authUser.role!=='admin'" class="account-card"><summary>注销账户</summary><p class="form-help">账户会停用，处理记录按服务器保留规则保存。有未完成任务时不能注销。</p><button class="button secondary" :disabled="busy" @click="action(async()=>{if(!confirm('确认注销当前账户？此操作不能在页面中恢复。'))return;await authRequest('/api/account/delete',{method:'POST',body:'{}'});authUser=null;emit('changed')})">注销当前账户</button></details>
    </template>
  </section>
</template>
